#pragma once

#include <cstdint>
#include <memory>
#include <string>

namespace ghostwheel {

// A report is valid only when it is generated by the model or decoded from a
// known, independently validated vehicle signal mapping. Observing bus bytes
// alone is NOT equivalent to measuring speed or actuator positions.
struct VehicleStatus {
  bool valid{false};
  double accel_report{0.0};
  double brake_report{0.0};
  double steer_report{0.0};
  double longitudinal_mps{0.0};
  double lateral_mps{0.0};
  double heading_rate_radps{0.0};
};

class VehicleHardwareInterface {
 public:
  virtual ~VehicleHardwareInterface() = default;
  virtual bool connect(std::string & reason) = 0;
  virtual void disconnect() noexcept = 0;

  // In this package, ONLY the synthetic HAL accepts actuation commands.
  // Physical implementations fail closed, with no CAN/UART writes.
  virtual bool send_command(double accel, double brake, double steer) = 0;
  virtual VehicleStatus read_status() = 0;
  virtual std::uint64_t observations() const noexcept = 0;
  virtual bool is_simulation() const noexcept = 0;
};

std::unique_ptr<VehicleHardwareInterface> make_sim_interface();
std::unique_ptr<VehicleHardwareInterface> make_can_monitor(const std::string & device);
std::unique_ptr<VehicleHardwareInterface> make_serial_monitor(
  const std::string & port, int baud_rate, bool obd_mode);

}  // namespace ghostwheel
